<?php

declare(strict_types=1);

namespace Eekes\Sulu\AiContentBundle\Application\Catalog;

use Symfony\Component\Yaml\Yaml;

/**
 * The catalog on disk. A missing file is an empty catalog: the assistant still works, it just
 * knows only what the field labels tell it.
 */
class CatalogFile
{
    private const string HEADER = <<<'YAML'
        # What the AI assistant knows about the templates and blocks of this project.
        #
        # Generated by "bin/adminconsole eekes:ai-content:analyze" and meant to be edited: sharpen
        # the descriptions, say when a block fits and when it does not, and list fields the
        # assistant must leave alone under exclude_fields. Run the command again after adding or
        # changing blocks; it describes what is new and never overwrites text you edited
        # (unless you pass --force).
        #
        # "fingerprint" and "generated" are bookkeeping for that command. Leave them as they are.

        YAML;

    private ?Catalog $catalog = null;

    private int|false $loadedAt = false;

    public function __construct(
        private readonly string $path,
    ) {
    }

    public function getPath(): string
    {
        return $this->path;
    }

    public function exists(): bool
    {
        return is_file($this->path);
    }

    public function load(): Catalog
    {
        // read again when the file changed: a worker lives longer than one edit of the catalog
        clearstatcache(true, $this->path);
        $modifiedAt = $this->exists() ? filemtime($this->path) : false;

        if ($this->catalog !== null && $modifiedAt === $this->loadedAt) {
            return $this->catalog;
        }

        $this->loadedAt = $modifiedAt;

        if ($modifiedAt === false) {
            return $this->catalog = new Catalog();
        }

        $data = Yaml::parseFile($this->path);

        return $this->catalog = Catalog::fromArray(\is_array($data) ? $data : []);
    }

    public function save(Catalog $catalog): void
    {
        $directory = \dirname($this->path);

        if (!is_dir($directory) && !mkdir($directory, 0o777, true) && !is_dir($directory)) {
            throw new \RuntimeException(\sprintf('Cannot create the directory "%s".', $directory));
        }

        $yaml = Yaml::dump($catalog->toArray(), 5, 4, Yaml::DUMP_MULTI_LINE_LITERAL_BLOCK | Yaml::DUMP_EMPTY_ARRAY_AS_SEQUENCE);
        file_put_contents($this->path, self::HEADER.$yaml);
        clearstatcache(true, $this->path);
        $this->catalog = $catalog;
        $this->loadedAt = filemtime($this->path);
    }
}
